// AGENT 1 of 3 - intent classifier. Runs first, feeds the specialist.
//
// Reads the webhook body exactly as it arrives - no reshaping node in front of
// it - and passes it on untouched apart from the intent it adds. Only a missing
// user falls back, to "sixdee".
//
// This is also the node that seeds the request's identity for the whole n8n
// execution. It is the only kind of AI node here that can set run metadata:
// n8n's native AI Agent node has no field for it and wraps its model in a proxy
// that discards any set on the instance. The proxy shares what this node
// declares with every other AI node of the same execution_id, which is how the
// two agents downstream reach the right Langfuse session and project.

const { ChatPromptTemplate } = require('@langchain/core/prompts');
const { StringOutputParser } = require('@langchain/core/output_parsers');

const item = $input.first().json;
const body = item.body || item;

const DEFAULT_USER = 'sixdee';

// Both ids are minted here if the caller did not send them, and ONLY here, so
// every agent, sub-agent, tool and node of this request shares one value.
//
// A generated sessionId is only useful if the caller gets it back and sends it
// with the next message, so both are echoed in the response.
const sessionId = body.sessionId || `SESSION-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
// msg_id identifies the user's MESSAGE, so it is minted once, here, where the
// message enters the system - and only carried from then on. Every agent,
// sub-agent, tool and node downstream reuses this value; none mint their own,
// because a second id would split one request into two traces.
const msgId = body.msg_id || `MSG-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const userId    = body.user_id || DEFAULT_USER;
const chatInput = body.chatInput || (body.message && body.message.payload) || '';

// withConfig metadata REPLACES what n8n injected on these runs, so the n8n
// execution id has to be put back by hand - it is the correlation key.
const executionId = String($execution.id);

const llm = await this.getInputConnectionData('ai_languageModel', 0);

const prompt = ChatPromptTemplate.fromMessages([
  ['system', 'Classify the user request as exactly one word: weather, billing or general.'],
  ['human', '{question}'],
]);

const chain = prompt.pipe(llm).pipe(new StringOutputParser()).withConfig({
  runName: `classify ${msgId}`,
  tags: ['node:crm', `msg:${msgId}`, 'agent:classifier'],
  metadata: {
    node: 'crm',
    session_id: sessionId,
    msg_id: msgId,
    // The trace represents the user's message, so say what that message was.
    // Left to guess, the proxy would take the first agent's prompt instead.
    user_input: chatInput,
    user_id: userId,
    route: body.route,
    workflow_name: 'Multi-Agent Support',
    agent: 'classifier',
    // Per-execution, not per-message: this is what you follow to debug or
    // replay this one agent. msg_id above is what ties the agents together.
    // Per node execution, not per message: this is what you follow to debug,
    // retry or replay this one agent. msg_id above is what ties them together.
    execution_id: executionId,
    node_execution_id: `classifier#${executionId}`,
    node_execution_id: `classifier#${executionId}`,
  },
});

const raw = await chain.invoke({ question: chatInput });

// The classifier answers in prose, so match rather than trust the whole string.
const lower = String(raw).toLowerCase();
const intent = ['weather', 'billing'].find((i) => lower.includes(i)) || 'general';

// The body as it came, plus what this agent worked out.
return [{ json: Object.assign({}, body, {
  sessionId, msg_id: msgId, user_id: userId, chatInput, intent,
}) }];

