// Plain n8n Code node - no LLM. Turns the classifier's verdict into the brief
// the specialist agent is given, so the routing decision is visible in the data
// rather than hidden in a branch.
const item = $input.first().json;

const briefs = {
  weather: 'You are a weather specialist. Use the calculator for any unit conversion.',
  billing: 'You are a billing specialist. Be precise about amounts and dates.',
  general: 'You are a general support agent.',
};

return [{ json: Object.assign({}, item, {
  specialistBrief: briefs[item.intent] || briefs.general,
  handedOffAt: new Date().toISOString(),
})}];

// Plain n8n Code node - no LLM. Carries the specialist's answer forward, since
// an AI Agent node emits only { output } and drops the rest of the item.
const answer = $input.first().json.output ?? '';
const ctx = $('Prepare Specialist Brief').first().json;

return [{ json: Object.assign({}, ctx, {
  specialistAnswer: answer,
  specialistAnsweredAt: new Date().toISOString(),
})}];

// Plain n8n Code node - no LLM. Assembles the reply from the three agent steps.
const ctx = $('Extract Specialist Answer').first().json;
const summary = $input.first().json.output ?? '';

return [{ json: {
  sessionId: ctx.sessionId,
  msg_id:    ctx.msg_id,
  user_id:   ctx.user_id,
  route:     ctx.route,
  intent:    ctx.intent,
  specialistAnswer: ctx.specialistAnswer,
  answer:    summary,
  agents:    ['classifier', 'specialist', 'summariser'],
}}];
